/* Lightweight, dependency-free canvas charts. Only JSON generated by the server is read. */
(() => {
  'use strict';
  const source = document.getElementById('analytics-data');
  if (!source) return;
  let data;
  try { data = JSON.parse(source.textContent); } catch (_) { return; }
  const colors = ['#e75c70','#e89552','#e5b449','#6a88b7','#38c2d4','#68bc9b'];
  const muted = '#879ab5', grid = '#263548', fg = '#dce3f0';
  const empty = rows => !rows.some(row => Number(row.count || row.events || row.alerts));
  const paint = (id, render) => {
    const el = document.getElementById(id);
    if (!el) return;
    const draw = () => {
      const rect = el.getBoundingClientRect();
      if (rect.width < 1 || rect.height < 1) return;
      const scale = Math.min(window.devicePixelRatio || 1, 2);
      el.width = Math.round(rect.width * scale);
      el.height = Math.round(rect.height * scale);
      const c = el.getContext('2d');
      c.scale(scale, scale);
      c.font = '12px system-ui, sans-serif';
      render(c, rect.width, rect.height);
    };
    if ('ResizeObserver' in window) new ResizeObserver(draw).observe(el);
    else window.addEventListener('resize', draw);
    draw();
  };
  const label = (c, txt, x, y, color = muted, align = 'left') => {
    c.fillStyle = color; c.textAlign = align; c.fillText(String(txt), x, y);
  };
  const noData = (c,w,h) => {
    c.textAlign='center'; c.fillStyle=muted;
    c.fillText('No recorded activity in this period', w/2,h/2);
  };
  paint('timeline-chart', (c,w,h) => {
    const rows=data.timeline;
    if(empty(rows)) return noData(c,w,h);
    const l=42,r=w-18,t=18,b=h-35, max=Math.max(1,...rows.map(x=>Math.max(x.events,x.alerts)));
    for(let i=0;i<=4;i++) {
      const y=b-(b-t)*i/4;
      c.strokeStyle=grid;c.beginPath();c.moveTo(l,y);c.lineTo(r,y);c.stroke();
      label(c,Math.round(max*i/4),l-9,y+4,muted,'right');
    }
    [['events','#38c2d4'],['alerts','#f09a61']].forEach(([key,color])=>{
      c.strokeStyle=color;c.lineWidth=2.5;c.beginPath();
      rows.forEach((row,i)=>{
        const x=l+(r-l)*(rows.length===1?0:i/(rows.length-1));
        const y=b-(b-t)*row[key]/max;
        if(i===0)c.moveTo(x,y); else c.lineTo(x,y);
      });c.stroke();
    });
    const tick=Math.max(1,Math.ceil(rows.length/7));
    rows.forEach((row,i)=>{
      if(i%tick===0||i===rows.length-1) label(c,data.granularity==='Monthly'?row.date:row.date.slice(5),l+(r-l)*i/Math.max(1,rows.length-1),h-9,muted,'center');
    });
  });
  paint('severity-chart',(c,w,h)=>{
    const rows=data.severity,total=rows.reduce((n,x)=>n+x.count,0);
    if(!total)return noData(c,w,h);
    const x=w*.36,y=h*.47,r=Math.min(w*.22,h*.34),thick=Math.max(16,r*.34);
    let angle=-Math.PI/2;
    rows.forEach((row,i)=>{
      if(!row.count)return;
      const sweep=row.count/total*Math.PI*2;
      c.beginPath();c.arc(x,y,r,angle,angle+sweep);c.lineWidth=thick;c.strokeStyle=colors[i];c.stroke();angle+=sweep;
    });
    c.font='bold 22px system-ui';label(c,total,x,y+7,fg,'center');c.font='12px system-ui';
    rows.forEach((row,i)=>{
      const ly=28+i*27;c.fillStyle=colors[i];c.fillRect(w*.63,ly-9,9,9);
      label(c,`${row.name}: ${row.count}`,w*.63+17,ly);
    });
  });
  const bars=(id, rows, color) => paint(id,(c,w,h)=>{
    if(empty(rows))return noData(c,w,h);
    const left=Math.min(125,Math.max(82,w*.32)),right=w-46,max=Math.max(...rows.map(r=>r.count),1);
    const rowH=Math.min(42,(h-24)/rows.length);
    rows.forEach((row,i)=>{
      const y=14+i*rowH;
      const name=row.name.length>17?row.name.slice(0,16)+'…':row.name;
      label(c,name,left-12,y+15,muted,'right');
      c.fillStyle=grid;c.fillRect(left,y,Math.max(1,right-left),18);
      c.fillStyle=color(i);c.fillRect(left,y,(right-left)*row.count/max,18);
      label(c,row.count,right+8,y+14,fg);
    });
  });
  bars('categories-chart',data.categories,i=>colors[(i+4)%colors.length]);
  bars('auth-chart',data.authentication,i=>i===0?'#e89552':'#68bc9b');
})();
